using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("/tmp/sv-322688fe42a9483e8b374c277f5f24d6/build.binlog");

// Find the Build target invocations and check which projects actually compiled
Console.WriteLine("=== TARGETS WITH ERRORS ===");
build.VisitAllChildren<Target>(target => {
    int errorCount = 0;
    target.VisitAllChildren<Error>(e => errorCount++);
    if (errorCount > 0) {
        Console.WriteLine($"  Target: {target.Name} in {target.Project?.Name} | Errors: {errorCount}");
    }
});

Console.WriteLine("\n=== CHECKING FOR Api COMPILATION ===");
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc") {
        var proj = task.GetNearestParent<Microsoft.Build.Logging.StructuredLogger.Project>();
        Console.WriteLine($"  Csc task in: {proj?.Name ?? "unknown"}");
    }
});
EOF
